"""Read-only model of invc.invc_customer; physical fields from PostgreSQL."""


class Table:
    def config_db(self, pkg):
        tbl = pkg.table('customer', name_long='!!Customer', name_plural='!!Customers', caption_field='account_name', partition_state='invc_state', pkey='id', sqlname='invc_customer', logicalDeletionField='__del_ts', draftField='__is_draft', lastTS='__mod_ts')
        tbl.column('id', dtype='C', notnull=True, size='22')
        tbl.column('__ins_ts', dtype='DH', notnull=False)
        tbl.column('__del_ts', dtype='DH', notnull=False)
        tbl.column('__mod_ts', dtype='DH', notnull=False)
        tbl.column('__ins_user', dtype='T', notnull=False)
        tbl.column('account_name', dtype='T', notnull=False, name_long='!!Account name', name_short='Account name', group='001')
        tbl.column('street_address', dtype='T', notnull=False, name_long='!!Street Address', name_short='St.Address', group='b_address.01')
        tbl.column('suburb', dtype='T', notnull=False, name_long='!!Suburb', name_short='!!Suburb', group='b_address.02')
        tbl.column('state', dtype='A', notnull=False, name_long='!!State', name_short='Pr.', group='b_address.04', size=':5').relation('invc.state.code', foreign_key=True, constraint_name='fk_0494e576', onDelete_sql='NO ACTION', onUpdate_sql='CASCADE', deferrable=False, initially_deferred=False, indexed=False)
        tbl.column('postcode', dtype='A', notnull=False, name_long='!!Postcode', name_short='Postcode', group='b_address.03', size=':5')
        tbl.column('customer_type_code', dtype='A', notnull=False, name_long='!!Customer type code', name_short='!!Cust type', group='002', size=':5').relation('invc.customer_type.code', foreign_key=True, constraint_name='fk_2e06787b', onDelete_sql='NO ACTION', onUpdate_sql='CASCADE', deferrable=False, initially_deferred=False, indexed=False)
        tbl.column('payment_type_code', dtype='A', notnull=False, name_long='!!Payment type code', name_short='!!Pay type', group='d_billing.01', size=':10').relation('invc.payment_type.code', foreign_key=True, constraint_name='fk_1152dd9b', onDelete_sql='NO ACTION', onUpdate_sql='CASCADE', deferrable=False, initially_deferred=False, indexed=False)
        tbl.column('notes', dtype='T', notnull=False, name_long='!!Notes', group='y_other.01')
        tbl.column('email', dtype='T', notnull=False, name_long='!!Email', group='c_contacts.01')
        tbl.column('phone', dtype='T', notnull=False, name_long='!!Phone', group='c_contacts.02')
        tbl.column('postcode_id', dtype='A', notnull=False, size=':22')
        tbl.column('__is_draft', dtype='B', notnull=False)
        tbl.column('access_token', dtype='T', notnull=False, name_long='!!Access Token', group='_')
        tbl.column('bank_account', dtype='T', notnull=False, name_long='!!Bank Account', group='d_billing.03')
        tbl.column('registration_id', dtype='T', notnull=False, name_long='!!Registration ID', group='d_billing.04')
        indexes = tbl.indexes()
        indexes.index(name='idx_14d21116', columns='state', unique=False, method='btree')
        indexes.index(name='idx_2e93b59e', columns='__ins_ts', unique=False, method='btree')
        indexes.index(name='idx_622d2da2', columns='payment_type_code', unique=False, method='btree')
        indexes.index(name='idx_aa67d575', columns='__mod_ts', unique=False, method='btree')
        indexes.index(name='idx_d4f373a5', columns='__del_ts', unique=False, method='btree')
        indexes.index(name='idx_e80d2c16', columns='customer_type_code', unique=False, method='btree')
        indexes.index(name='invc_customer___is_draft_idx', columns='__is_draft', unique=False, method='btree')

        tbl.formulaColumn('n_invoices', select=dict(table='invc.invoice', columns='COUNT(*)', where='$customer_id=#THIS.id'), dtype='L', name_long='N.Invoices', group='e_activity.01')
        tbl.formulaColumn('invoiced_total', select=dict(table='invc.invoice', columns='SUM($total)', where='$customer_id=#THIS.id'), dtype='N', name_long='Invoiced Total', group='e_activity.02')
        tbl.formulaColumn('last_invoice_id', select=dict(table='invc.invoice', columns='$id', where='$customer_id=#THIS.id', order_by='$date DESC', limit=1), dtype='T', name_long='Last Invoice', group='e_activity.04').relation('invoice.id', foreign_key=False, relation_name='last_invoice', one_group='e_activity.04')
        tbl.formulaColumn('full_address', sql_formula="$street_address || ', ' || $suburb", dtype='T', name_long='Full Address', group='b_address.05')
        tbl.formulaColumn('has_invoices', exists=dict(table='invc.invoice', where='$customer_id=#THIS.id'), dtype='B', name_long='Has Invoices', group='e_activity.06')
        tbl.formulaColumn('customer_rank', sql_formula="CASE WHEN $n_invoices = 0 THEN 'Inactive' WHEN $n_invoices < 5 THEN 'Occasional' ELSE 'Regular' END", dtype='A', name_long='Customer Rank', group='005')
        tbl.formulaColumn('display_name', sql_formula="COALESCE($account_name, 'Unknown')", dtype='T', name_long='Display Name', group='003')
        tbl.formulaColumn('postcode_padded', sql_formula="LPAD($postcode, 5, '0')", dtype='T', name_long='Postcode Padded', group='b_address.06')
        tbl.aliasColumn('state_name', relation_path='@state.name', name_long='State Name', group='b_address.07')
        tbl.aliasColumn('payment_description', relation_path='@payment_type_code.description', name_long='Payment Description', group='d_billing.02')
        tbl.aliasColumn('region_name', relation_path='@state.@region_code.name', name_long='Region Name', group='b_address.08')
        tbl.formulaColumn('account_code', sql_formula="LPAD(CAST($id AS TEXT), 8, '0')", dtype='T', name_long='Account Code', group='004')
        tbl.formulaColumn('is_active_valuable', sql_formula='$has_invoices AND $n_invoices >= 3', dtype='B', name_long='Active Valuable Customer', group='e_activity.08')
        tbl.formulaColumn('contact_info', sql_formula="CONCAT(COALESCE($email, 'no-email'), ' | ', COALESCE($phone, 'no-phone'))", dtype='T', name_long='Contact Info', group='c_contacts.03')
        tbl.formulaColumn('customer_score', sql_formula="10 + CASE WHEN COALESCE($email,'') <> '' THEN 5 ELSE 0 END", dtype='N', name_long='Customer Score', group='e_activity.09')
        tbl.formulaColumn('invoice_numbers', sql_formula="array_to_string(ARRAY(#inv_nums), ', ')", select_inv_nums=dict(table='invc.invoice', columns='$inv_number', where='$customer_id=#THIS.id', order_by='$date DESC', limit=5), dtype='T', name_long='Invoice Numbers', group='e_activity.05')
        tbl.formulaColumn('avg_invoice_value', sql_formula='$invoiced_total / NULLIF($n_invoices, 0)', dtype='N', name_long='Avg Invoice Value', group='e_activity.03')
        tbl.formulaColumn('has_activity', sql_formula='$has_invoices OR EXISTS(SELECT 1 FROM invc.invc_invoice_note AS n INNER JOIN invc.invc_invoice AS i ON n.invoice_id = i.id WHERE i.customer_id = #THIS.id)', dtype='B', name_long='Has Activity', group='e_activity.07')
        tbl.formulaColumn('is_confirmed', sql_formula='$__is_draft IS NOT TRUE', dtype='B', name_long='Is Confirmed', group='006')
